tion value="made_for_kids" <?= $field('audience',$yt['audience']??'')==='made_for_kids'?'selected':'' ?>>สร้างมาสำหรับเด็ก</option></select></div><label class="form-check mt-3"><input type="checkbox" class="form-check-input" name="synthetic_media" <?= ($post?isset($post['synthetic_media']):($yt['synthetic_media']??false))?'checked':'' ?>><span class="form-check-label">มีเนื้อหาสังเคราะห์/ดัดแปลงที่ต้องเปิดเผย</span></label><?php endif; ?></div><?php endforeach; ?></div></section><div class="form-footer"><span class="text-secondary">บันทึกร่างก่อน แล้วตรวจ Preview เพื่อส่งอนุมัติ</span><button class="btn btn-primary" type="submit">บันทึกร่าง →</button></div></form>

